Body:
> Is there any way to manually enable it?

manually override in your `opencode.json`
```json
        "gpt-5.3-codex": {
          "name": "GPT-5.3 Codex",
          "limit": {
            "context": 400000,
            "output": 128000
          },
          "options": {
            "serviceTier": "priority"
          },
          "modalities": {
            "input": [
              "text",
              "image",
              "pdf"
            ],
            "output": [
              "text"
            ]
          },
          "variants": {
            "xhigh": {
              "reasoningEffort": "xhigh",
              "textVerbosity": "low",
            },
            "high": {
              "reasoningEffort": "high",
              "textVerbosity": "low",
            },
            "medium": {
              "reasoningEffort": "medium",
              "textVerbosity": "low",
            },
            "low": {
              "reasoningEffort": "low",
              "textVerbosity": "low",
            },
            "none": {
              "reasoningEffort": "none",
              "textVerbosity": "low",
            }
          },
        }
```
